<script setup lang="ts">
import {ref} from 'vue';import {FileText,Upload,ShieldCheck,Bell,X,CalendarDays} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {useVintro} from '../composables/useVintro';import {useSelectedVehicle} from '../composables/useSelectedVehicle';import type {DocumentCategory} from '../data/customer';
const {state,addDocument}=useVintro();const {base}=useSelectedVehicle();const adding=ref(false);const uploading=ref(false);const categories:DocumentCategory[]=['Registration certificate','Insurance policy','Technical inspection','Homologation','Leasing documents','Service invoice','Repair invoice','Warranty document','Other'];const form=ref({name:'',category:'Service invoice' as DocumentCategory,issueDate:'2026-08-26',expirationDate:'',reminder:false});
const save=()=>{uploading.value=true;setTimeout(()=>{addDocument({id:crypto.randomUUID(),name:form.value.name||form.value.category,category:form.value.category,issueDate:form.value.issueDate,expirationDate:form.value.expirationDate||undefined,reminder:form.value.reminder,size:'PDF · 420 KB',verified:false});uploading.value=false;adding.value=false;form.value.name=''},600)}

</script>
<template><PageHeader title="Documents" :back="base"/><div class="container-app max-w-3xl py-7"><p class="eyebrow">Vehicle archive</p><h1 class="page-title mt-2">Documents</h1><p class="mt-3 max-w-xl text-muted">Keep invoices, certificates and important vehicle files together.</p><button @click="adding=true" class="mt-8 flex min-h-36 w-full flex-col items-center justify-center rounded-2xl border border-dashed bg-white text-sm font-medium hover:bg-stone-50"><Upload :size="22"/><span class="mt-3">Upload a document</span><small class="mt-1 font-normal text-muted">PDF, JPG or PNG · prototype upload</small></button><section class="mt-8"><div class="flex items-center justify-between"><h2 class="section-title">Stored documents</h2><span class="text-sm text-muted">{{state.documents.length}} files</span></div><div class="mt-3 divide-y rounded-2xl border bg-white"><button v-for="doc in state.documents" :key="doc.id" class="flex w-full items-center gap-4 p-4 text-left hover:bg-stone-50"><span class="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-stone-100"><FileText :size="20"/></span><span class="min-w-0 flex-1"><strong class="block truncate text-sm">{{doc.name}}</strong><small class="mt-1 block text-muted">{{doc.category}} · {{doc.size}}</small><small v-if="doc.expirationDate" class="mt-1 flex items-center gap-1 text-amber"><CalendarDays :size="12"/>Expires {{doc.expirationDate}}</small></span><Bell v-if="doc.reminder" :size="17" class="text-amber"/><ShieldCheck v-if="doc.verified" :size="18" class="text-success"/></button></div></section><div class="mt-6 rounded-2xl bg-stone-100 p-5 text-sm leading-6 text-muted"><strong class="block text-ink">Vintro Plus</strong>Unlimited document storage and cloud sync will be part of Vintro Plus.</div></div><Teleport to="body"><div v-if="adding" class="fixed inset-0 z-[80] flex items-end bg-black/30 backdrop-blur-sm" @click.self="adding=false"><form @submit.prevent="save" class="mx-auto w-full max-w-xl rounded-t-3xl bg-white p-6 pb-10"><div class="flex items-center justify-between"><h2 class="text-2xl font-semibold">Add document</h2><button type="button" @click="adding=false" class="grid h-10 w-10 place-items-center rounded-full bg-stone-100"><X :size="18"/></button></div><label class="mt-6 block"><span class="label">Document name</span><input v-model="form.name" class="field" placeholder="e.g. Insurance policy 2026" required/></label><label class="mt-4 block"><span class="label">Category</span><select v-model="form.category" class="field"><option v-for="c in categories">{{c}}</option></select></label><div class="mt-4 grid grid-cols-2 gap-3"><label><span class="label">Issue date</span><input v-model="form.issueDate" type="date" class="field nums"/></label><label><span class="label">Expiration date</span><input v-model="form.expirationDate" type="date" class="field nums"/></label></div><label class="mt-4 flex items-center justify-between rounded-xl bg-stone-50 p-4 text-sm"><span><strong class="block">Expiration reminder</strong><small class="text-muted">Notify me before it expires</small></span><input v-model="form.reminder" type="checkbox" class="h-5 w-5 accent-[#2d5b4f]"/></label><button class="btn-primary mt-6 w-full" :disabled="uploading"><span v-if="uploading" class="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"/>{{uploading?'Uploading…':'Add document'}}</button></form></div></Teleport></template>
